// Guard to temporarily mutate a values type
class MutateTypeGuard {
    Value *value;
    Type *savedTy;
public:
    MutateTypeGuard(Value *value, Type *mutateTy): value(value) {
        savedTy = value->getType();
        value->mutateType(mutateTy);
    }
    
    ~MutateTypeGuard() {
        value->mutateType(savedTy);
    }
};

struct SectionTypeConfig {
    const char* sectionName;
    const char* object;
    std::list<const char*> match_list;
    std::list<const char*> INITLIST;
    const char* startPrefix;
    const char* startPostfix;
    const char* endPrefix;
    const char* endPostfix;
    const char* namePrefix;
    const char* namePostfix;
};

